// Moeda com o ícone de um polo de eixo (o mesmo do resultado), para valores que representam esse polo.
function poleCoin(axisId: string, side: 'left' | 'right'): CoinStyle {
  const icon = FILLED_POLE_ICONS[axisId][side]!;
  return {
    viewBox: icon.viewBox,
    glyph: icon.paths.map((d) => <path key={d} d={d} fillRule={icon.fillRule ?? 'evenodd'} />)
  };
}

